Here’s a Python example using `Decimal` for currency. Discounts are percentages applied to the cart subtotal; an unknown code raises an error.

```python
from decimal import Decimal, ROUND_HALF_UP

DISCOUNTS = {
    "SAVE10": Decimal("0.10"),
    "SAVE20": Decimal("0.20"),
}

def calculate_total(products, discount_code=None):
    """
    products: iterable of {"price": "12.50", "quantity": 2}
    Returns the final price as a Decimal.
    """
    subtotal = Decimal("0")

    for product in products:
        price = Decimal(str(product["price"]))
        quantity = product["quantity"]

        if not price.is_finite() or price < 0:
            raise ValueError("Prices must be finite and non-negative")
        if isinstance(quantity, bool) or not isinstance(quantity, int) or quantity < 0:
            raise ValueError("Quantities must be non-negative integers")

        subtotal += price * quantity

    discount = Decimal("0")
    if discount_code:
        code = discount_code.strip().upper()
        if code not in DISCOUNTS:
            raise ValueError("Invalid discount code")
        discount = DISCOUNTS[code]

    return (subtotal * (Decimal("1") - discount)).quantize(
        Decimal("0.01"), rounding=ROUND_HALF_UP
    )


cart = [
    {"price": "12.50", "quantity": 2},
    {"price": "8.00", "quantity": 1},
]

print(calculate_total(cart, "SAVE10"))  # 29.70
```

This calculates the price before taxes and shipping.

